const item = $input.first().json;
const question = item.question || item.query || item.prompt || '';

return [{
  json: {
    question: question,
    needs_attendance: true,
    needs_mail: true
  }
}];

const qItem = $('Prepare Multi-Source Queries').first().json;
const attItems = $('Fetch Attendance Evidence').all();
const mailItems = $('Fetch Project Mail Evidence').all();

let attText = '';
attItems.forEach(i => {
  const r = i.json;
  attText += `- ${r.full_name} (${r.department}): ${r.status}, Giriş: ${r.first_in || 'Yok'}, Gecikme: ${r.late_minutes || 0} dk\n`;
});
if (!attText) attText = 'Bugün için özel bir gecikme kaydı bulunamadı.';

let mailText = '';
mailItems.forEach(i => {
  const r = i.json;
  mailText += `- [${r.project_code || 'GENEL'}] ${r.subject} (${r.from_address}): ${r.content}\n`;
});
if (!mailText) mailText = 'İlgili güncel proje e-postası bulunamadı.';

const prompt = `Sen Eldor/NISO AI kurumsal yönetim asistanısın. Aşağıdaki çoklu kaynak verilerini (Puantaj/Vardiya durumu ve Proje E-Postaları) analiz ederek yöneticinin sorusuna kapsamlı ve net bir Türkçe özet hazırla.\n\nÇOK ÖNEMLİ KURAL (NEDENSELLİK ŞARTI):\n1. Puantaj verisi ile proje aksamaları/riskleri arasındaki korelasyon veya zamansal çakışma, doğrudan bir sebep-sonuç ilişkisini KANITLAMAZ.\n2. Raporunda verileri mutlaka ayrı bölümlerde sun ve cevabın sonuna şu resmi notu ekle: '(Not: Puantaj/katılım durumu ile proje aksaklıkları arasındaki zamansal çakışmalar korelasyon niteliğindedir; doğrudan nedensellik kanıtı sayılmaz.)'\n\n1. BÖLÜM: PERSONEL & KATILIM DURUMU\n${attText}\n\n2. BÖLÜM: PROJE DURUMU & E-POSTA AKIŞI\n${mailText}\n\nYÖNETİCİ SORUSU: ${qItem.question}\n\nCEVAP:`;

return [{
  json: {
    question: qItem.question,
    prompt: prompt
  }
}];

const llmRes = $input.first()?.json || {};
let answer = (llmRes.response || '').trim();
if (!answer && llmRes.thinking) {
  const match = llmRes.thinking.match(/(\n\*\*[A-ZÇĞİÖŞÜ][\s\S]+)/i) || llmRes.thinking.match(/(\n#[\s\S]+)/i);
  if (match) answer = match[0].trim();
}
if (!answer) {
  answer = 'İlgili devam verileri ve proje e-postaları birleştirilerek incelenmiştir.';
}

if (!answer.includes('nedensellik')) {
  answer += '\n\n*(Not: Puantaj/katılım durumu ile proje aksaklıkları arasındaki zamansal çakışmalar korelasyon niteliğindedir; doğrudan nedensellik kanıtı sayılmaz.)*';
}

return [{
  json: {
    status: 'SUCCESS',
    intent: 'HYBRID',
    title: 'Hibrit Analiz',
    answer: answer,
    route_used: 'HYBRID',
    causality_disclaimer: true,
    timestamp: new Date().toISOString()
  }
}];
